window.EXPLAIN=window.EXPLAIN||{};window.EXPLAIN.ua={"10081":{"law":"art. 31 ust. 2 pkt 1 Prawa o ruchu drogowym","text":"Автомобіль із несправним кермовим керуванням не можна буксирувати жодним способом, бо ним неможливо керувати за тягачем. Такий транспорт перевозять на евакуаторі."},"10109":{"law":"art. 31 ust. 2 pkt 1 Prawa o ruchu drogowym","text":"Буксирований мотоцикл повинен мати справні обидві гальмівні системи, передню й задню, бо гальмує сам за себе. Швидкість тут значення не має."},"10805":{"law":"art. 5 ust. 1 Prawa o ruchu drogowym","text":"Вказівок супроводу негабаритного транспорту треба слухатися так само, як сигналів поліцейського, бо супровід керує рухом на час проїзду. Його сигнали мають перевагу над знаками."},"10806":{"law":"art. 39 ust. 3 Prawa o ruchu drogowym","text":"Крісло проти напрямку руху на передньому сидінні допустиме лише при вимкненій подушці пасажира. Подушка, що спрацьовує, б'є тоді просто в голову дитини."},"10815":{"text":"Крісло встановлюють точно так, як описав виробник, бо лише в цій конфігурації воно пройшло краш-тести. Зручність і естетика тут ні до чого."},"10816":{"law":"art. 135 ust. 1 pkt 1a Prawa o ruchu drogowym","text":"Поліцейський вилучає посвідчення при перевищенні швидкості більш ніж на 50 км/год у населеному пункті. Рівно 50 км/год це ще не той випадок, а поза населеним пунктом норма не діє."},"10819":{"text":"Рішення про вилучення посвідчення староста видає при перевищенні більш ніж на 50 км/год у населеному пункті. Поза населеним пунктом ця норма не діє."},"10822":{"text":"Посвідчення затримують на 3 місяці. Якщо водій попри це керує, строк подовжують до 6 місяців, а при новому порушенні загрожує анулювання права керування."},"10829":{"law":"art. 71 ust. 1 Prawa o ruchu drogowym","text":"Допуск транспортного засобу до руху підтверджує свідоцтво про реєстрацію. Картка транспортного засобу фіксує його історію, а контрольну наліпку з 2019 року вже не застосовують."},"10840":{"law":"art. 39 ust. 3 Prawa o ruchu drogowym","text":"Дитину, нижчу за 150 см, перевозять у кріслі або іншому пристрої, підібраному за зростом і вагою. На колінах пасажира дитину возити не можна ніколи."},"10869":{"law":"art. 39 ust. 3 Prawa o ruchu drogowym","text":"Дитина, нижча за 150 см, має їхати в кріслі або іншому пристрої, зокрема й спереду. Без пристрою і без застебнутих пасів возити її не можна ніде."},"10871":{"text":"Крісло встановлюють згідно з інструкцією виробника, бо лише так працюють його кріплення і паси. Зручність дорослого чи дитини правил монтажу не змінює."},"10872":{"text":"Утримувальний пристрій встановлюють у спосіб, рекомендований виробником, бо саме так його випробували й допустили. Імпровізація при монтажі перекреслює весь захист."},"10874":{"law":"art. 39 ust. 3 Prawa o ruchu drogowym","text":"Дитину віком до трьох років можна возити лише в авто з пасами безпеки і в дитячому кріслі. Без пасів крісло не закріпити, тож таким транспортом дитину не перевозять."},"10876":{"text":"Крісло добирають за технічними умовами: омологацією, зростом і вагою дитини. Зручність і вигляд другорядні, бо захист визначає відповідність нормі."},"10878":{"law":"art. 39 ust. 3a Prawa o ruchu drogowym","text":"Дитину зростом щонайменше 135 см можна возити на задньому сидінні лише в пасах, якщо її зріст і вага унеможливлюють використання крісла. Межа це 135 см, а не 125 см, і жодного обмеження швидкості тут немає."},"10880":{"law":"art. 39 ust. 3a Prawa o ruchu drogowym","text":"Умова це зріст щонайменше 135 см і те, що зріст та вага дитини унеможливлюють використання утримувального пристрою. Обмеження швидкості до цього стосунку не має."},"10882":{"law":"art. 39 ust. 3 pkt 1 Prawa o ruchu drogowym","text":"Якщо двоє дітей уже їдуть у кріслах і третє встановити неможливо, третю дитину віком понад 3 роки можна пристебнути лише пасами. На колінах дорослого дитину не возять ніколи."},"10883":{"law":"art. 39 ust. 3 pkt 1 Prawa o ruchu drogowym","text":"Третю дитину, для якої не лишилося місця під утримувальний пристрій, фіксують пасами безпеки. Підставка під ноги чи місце посередині дивана нічого не змінюють."},"10885":{"law":"art. 38 Prawa o ruchu drogowym","text":"Треба мати при собі квитанцію про вилучення свідоцтва про реєстрацію, доки вона дозволяє керувати. Саме свідоцтво і підтвердження оплати ОЦВ у Польщі возити не потрібно, дані є в реєстрі."},"10886":{"law":"art. 38 Prawa o ruchu drogowym","text":"Возять квитанцію про вилучення тимчасового посвідчення, доки воно дозволяє користуватися транспортом. Каско добровільне, а довідку про техогляд мати при собі не треба."},"10887":{"law":"art. 38 Prawa o ruchu drogowym","text":"Із 2018 року свідоцтво про реєстрацію возити не треба, а от квитанцію про його вилучення так, бо саме вона тоді замінює документ на авто. Поліцейський перевіряє дані в центральному реєстрі."},"10888":{"law":"art. 38 Prawa o ruchu drogowym","text":"Обов'язковою є квитанція про вилучення тимчасового посвідчення в період, коли воно дозволяє керувати. Ні сертифіката відповідності ЄС, ні свідоцтва про реєстрацію возити не треба."},"10889":{"law":"art. 38 pkt 3 Prawa o ruchu drogowym","text":"Керуючи авто, зареєстрованим за кордоном, треба мати документ про допуск до руху, бо цього транспорту немає в польських базах. Страхування від нещасних випадків добровільне, а копія техогляду нічого не замінює."},"10890":{"law":"art. 38 pkt 3 Prawa o ruchu drogowym","text":"При транспорті, зареєстрованому за кордоном, возять документ про укладення обов'язкового ОЦВ. Польські бази не містять даних про страхування такого авта."},"10891":{"law":"art. 38 pkt 3 Prawa o ruchu drogowym","text":"При авто, зареєстрованому за кордоном, треба мати доказ сплати внеску ОЦВ. Плата за автомагістралі й документ про власність не належать до потрібних під час перевірки."},"10892":{"law":"art. 38 pkt 1 Prawa o ruchu drogowym","text":"Польське посвідчення возити не треба, бо право керування є в реєстрі, а от іноземний документ мати при собі обов'язково. Свідоцтво кваліфікації стосується лише професійних водіїв."},"10893":{"law":"art. 38 Prawa o ruchu drogowym","text":"Квитанцію про вилучення посвідчення треба мати при собі, бо в цей час вона замінює документ на право керування. Медичні та психологічні висновки стосуються професійних водіїв."},"10894":{"law":"art. 38 Prawa o ruchu drogowym","text":"Водій має при собі квитанцію про вилучення посвідчення протягом строку, коли вона дає право керувати. Психологічний і медичний висновки для звичайного водія до цього переліку не входять."},"10895":{"law":"art. 38 pkt 1 Prawa o ruchu drogowym","text":"Обов'язковим є документ на право керування, інший ніж польське посвідчення, наприклад іноземне чи міжнародне. Довідки про курси не є документами дорожньої перевірки."},"10898":{"law":"art. 135 ust. 1 pkt 2 Prawa o ruchu drogowym","text":"Посвідчення забирають за перевезення осіб у кількості, що перевищує кількість місць у свідоцтві про реєстрацію. Обгін через суцільну і роз'їзд на переїзді це штраф і бали, але документа за них не втрачаєш."},"10899":{"law":"art. 135 ust. 1 pkt 2 Prawa o ruchu drogowym","text":"Підставою для вилучення посвідчення є перевезення осіб понад кількість місць, зазначену в тимчасовому посвідченні. Обгін перед переходом із регульованим рухом законний, а роз'їзд на велопереїзді це порушення без втрати документа."},"10930":{"text":"Квитанція дає право керувати протягом 24 годин від моменту вилучення посвідчення. Після цього керування вважається їздою без права керування."},"10931":{"text":"І тут квитанція діє 24 години, незалежно від того, за що посвідчення забрали. Строк рахують від моменту вилучення документа."},"10960":{"law":"art. 135 ust. 1a Prawa o ruchu drogowym","text":"Посвідчення не забирають, якщо перевищення швидкості служило порятунку життя чи здоров'я. Норма прямо виключає дії в стані крайньої необхідності."},"10961":{"law":"art. 135 ust. 1a Prawa o ruchu drogowym","text":"Поліцейський не вилучатиме посвідчення, бо водій діяв заради порятунку людського життя. Ні попередження з контрольним іспитом, ні додаткового навчання тут немає."},"10992":{"law":"art. 39 ust. 3 pkt 1 Prawa o ruchu drogowym","text":"Третю дитину можна пристебнути лише пасами тоді, коли двоє вже сидять у кріслах, третє встановити неможливо, а дитині виповнилося 3 роки. Ні зріст 100 см, ні вік 15 років тут умовою не є."},"10994":{"law":"art. 39 ust. 4 Prawa o ruchu drogowym","text":"Виняток дає виключно медична довідка про протипоказання до перевезення в кріслі. Брак місця під крісло чи зріст 135 см від обов'язку на передньому сидінні не звільняють."},"11001":{"law":"art. 38 Prawa o ruchu drogowym","text":"Водій, чиє право керування обмежене авто з алкоблокуванням, мусить возити довідку про технічний огляд у цій частині. Свідоцтво про реєстрацію і підтвердження ОЦВ возити не треба."},"11003":{"text":"Інспектор автомобільного транспорту має в цій частині такі самі повноваження, як поліція, і може перевірити авто в центральному реєстрі. Перевірка транспорту без доступу до цих даних була б формальною."},"11005":{"law":"art. 132 ust. 5 Prawa o ruchu drogowym","text":"Свідоцтво про реєстрацію повертає станція технічного контролю після огляду, що відповідає причині вилучення. Лише підтвердження усунення несправності повертає документ."},"11017":{"text":"За перевищення швидкості більш ніж на 50 км/год у населеному пункті посвідчення затримують на 3 місяці. Керування попри заборону подовжує цей строк до 6 місяців."},"11018":{"text":"Квитанція дозволяє керувати протягом 24 годин від вилучення посвідчення. Це потрібно, щоб дістатися додому, а не щоб їздити далі як зазвичай."},"11022":{"law":"art. 135 ust. 1a Prawa o ruchu drogowym","text":"Винятком є дія задля усунення безпосередньої небезпеки для правоохоронюваного блага, тобто крайня необхідність. Тиск іншого водія чи бажання швидше звільнити перехрестя нічого не виправдовують."},"11028":{"law":"art. 39 ust. 3 Prawa o ruchu drogowym","text":"При активній подушці пасажира дитину можна возити спереду лише в кріслі, повернутому за напрямком руху. Будь-яке розташування проти руху вимагає вимкнення подушки."},"11528":{"law":"art. 135 ust. 1 pkt 2 Prawa o ruchu drogowym","text":"Перевищення кількості місць на дві особи чи більше коштує затримання посвідчення на 3 місяці. Контрольної перевірки кваліфікації тут не передбачено."},"13052":{"law":"art. 19 ust. 3 Prawa o ruchu drogowym","text":"Жорстко визначена мінімальна дистанція діє на автомагістралі та швидкісній дорозі: щонайменше половина показника спідометра, виражена в метрах. На інших дорогах дистанція має бути просто безпечною."},"13054":{"law":"art. 20 ust. 5 Prawa o ruchu drogowym","text":"Транспорт із пристроєм, що виступає вперед більш ніж на 1,5 м від сидіння водія, може рухатися щонайбільше 30 км/год у населеному пункті і 60 км/год поза ним. Виступ закриває дорогу просто перед авто, звідси й знижений ліміт."},"13058":{"law":"art. 19 ust. 1 i art. 20 ust. 3 Prawa o ruchu drogowym","text":"На автомагістралі легковик може рухатися щонайбільше 140 км/год, і лише тоді, коли умови дозволяють контролювати авто. Ліміт це верхня межа, а не рекомендована швидкість."},"13064":{"law":"art. 20 ust. 1 Prawa o ruchu drogowym","text":"У населеному пункті діє 50 км/год, і це стосується також квадроцикла, незалежно від його маси. Маса змінює ліміти лише поза населеним пунктом і для составів із причепом."},"13088":{"law":"art. 31 ust. 1 pkt 3 Prawa o ruchu drogowym","text":"Буксирувати дозволено щонайбільше 30 км/год у населеному пункті і 60 км/год поза ним. Буксирований автомобіль часто має слабші гальма і не має підсилювача, тож швидше просто небезпечно."},"13382":{"law":"art. 39 ust. 4 Prawa o ruchu drogowym","text":"Єдиний виняток дає медична довідка про протипоказання до перевезення в кріслі. Повільніша їзда чи наліпка про дитину в салоні від обов'язку не звільняють."},"13402":{"law":"art. 26 ust. 6 Prawa o ruchu drogowym","text":"Біла тростина позначає незрячу людину, і тоді водій зобов'язаний зупинити авто і дати їй перейти, зокрема й поза переходом. Звуковий сигнал таку людину лише дезорієнтує."},"13404":{"law":"art. 26 ust. 1 i 6 Prawa o ruchu drogowym","text":"Людині з видимою інвалідністю потрібно більше часу, тож треба заздалегідь припускати, що доведеться зупинитися. Під'їжджати до переходу зі швидкістю, яка цього не дозволяє, це помилка."},"13460":{"law":"art. 28 ust. 6 Prawa o ruchu drogowym","text":"Якщо автомобіль неможливо прибрати з колії, треба попередити машиніста, бо потяг гальмує сотні метрів. Попереджають із належної відстані, подаючи чіткий сигнал, видимий із локомотива."},"13461":{"law":"art. 28 ust. 5 i 6 Prawa o ruchu drogowym","text":"Насамперед треба прибрати автомобіль із переїзду, і лише якщо це не вдається, попереджати машиніста. Порядок саме такий, бо вільний переїзд розв'язує проблему, а попередження лише сигналізує про неї."},"13463":{"text":"Шлагбауми зроблені так, щоб їх можна було зламати, якщо авто застрягло між ними. Краще зруйнувати шлагбаум, ніж лишитися на колії перед потягом."},"13464":{"law":"art. 28 ust. 3 pkt 1 Prawa o ruchu drogowym","text":"Коли півшлагбауми починають опускатися, в'їзд на переїзд уже заборонений, попри будь-яку обережність. Опускання означає, що потяг у дорозі і за мить буде на переїзді."},"13522":{"law":"art. 26 ust. 6 Prawa o ruchu drogowym","text":"Щодо особи з видимо обмеженою рухливістю обов'язок зупинитися діє також поза пішохідним переходом. Така людина не встигне ні відійти, ні відступити перед авто."},"13540":{"law":"art. 23 ust. 1 pkt 1 Prawa o ruchu drogowym","text":"Об'їжджаючи пішохода, треба тримати безпечний інтервал, а за потреби знизити швидкість. Пішохід може зробити крок убік, тож близький проїзд на повній швидкості виключений."},"13551":{"law":"art. 30 ust. 3 Prawa o ruchu drogowym","text":"У тумані поза населеним пунктом водій механічного транспорту подає короткочасні звукові сигнали під час обгону, зокрема й обганяючи пішохода. Пішохід не почує тихого авта і не встигне зійти з дороги."},"13552":{"law":"art. 30 ust. 3 Prawa o ruchu drogowym","text":"Той самий обов'язок стосується об'їзду: у тумані поза населеним пунктом подають короткочасні звукові сигнали. Ідеться про те, щоб пішохід почув авто, перш ніж воно порівняється з ним."},"13553":{"law":"art. 26 ust. 6 Prawa o ruchu drogowym","text":"На зупинці без острівця пасажири виходять просто на проїзну частину, тож водій мусить зупинитися так, щоб вони мали вільний прохід до транспорту. Проїзд повз автобус, що стоїть, без зупинки це порушення."},"13560":{"law":"art. 19 ust. 1 Prawa o ruchu drogowym","text":"Обов'язок рухатися зі швидкістю, що забезпечує контроль над транспортом, стосується кожного водія, зокрема велосипедиста і візника. Він не залежить ні від типу транспорту, ні від зони."},"13561":{"law":"art. 19 ust. 1 Prawa o ruchu drogowym","text":"Безпечна швидкість це та, за якої ти контролюєш транспорт у наявних умовах. Вона часто значно нижча за дозволену, наприклад на кризі чи в тумані."},"13562":{"law":"art. 19 ust. 1 Prawa o ruchu drogowym","text":"Їдеш настільки швидко, щоб зупинитися перед перешкодою на видимому відрізку дороги, незалежно від ліміту. Уночі чи в тумані це означає швидкість значно нижчу за дозволену."},"13569":{"text":"Що швидше їдеш, то менше часу лишається помітити небезпеку і зреагувати. Час реакції приблизно сталий, тож на більшій швидкості авто долає за цей час довшу відстань."},"13570":{"text":"Енергія удару зростає пропорційно квадрату швидкості, тож швидкість визначає наслідки будь-якої аварії, а не лише лобової. Різниця між 50 і 70 км/год це різниця між пом'ятим крилом і загибеллю."},"13580":{"law":"art. 19 ust. 1 Prawa o ruchu drogowym","text":"Уночі на звивистій неосвітленій дорозі світло сягає ближче, ніж зупинковий шлях на максимальному ліміті. Треба їхати так, щоб зупинитися в межах власного світла."},"13592":{"text":"Транспорт, що рухається дуже швидко, важче помітити, бо інші оцінюють відстань і час під'їзду за типовими швидкостями. Тому водій, який виїжджає на дорогу, опиняється просто перед розігнаним авто."},"13593":{"text":"На 120 км/год авто долає близько 33 метрів за секунду, тож секунда зволікання це понад тридцять метрів довший зупинковий шлях. Цього досить, щоб зіткнення вже не вдалося уникнути."},"13594":{"text":"100 км/год це близько 28 метрів за секунду, бо кілометри на годину ділять на 3,6. Цей перерахунок варто запам'ятати: на 50 км/год авто долає приблизно 14 метрів за секунду."},"13604":{"law":"art. 33a ust. 3 Prawa o ruchu drogowym","text":"Електросамокат розрахований на одну особу, і перевозити пасажира заборонено. Друга людина зміщує центр ваги й подовжує гальмівний шлях транспорту, який і так гальмує слабко."},"13609":{"law":"art. 60 ust. 2 pkt 4 Prawa o ruchu drogowym","text":"Буксирувати за транспортом особу на пристрої для пересування, як-от самокаті чи роликах, заборонено. Така людина не має змоги ні гальмувати, ні реагувати на дії водія."},"13615":{"law":"art. 33a ust. 2 Prawa o ruchu drogowym","text":"Пішохідною доріжкою можна користуватися у виняткових випадках, коли немає велодоріжки, а дозволена швидкість на проїзній частині перевищує 30 км/год. Тоді рухаються зі швидкістю пішохода і поступаються йому."},"13618":{"law":"art. 28 ust. 1 Prawa o ruchu drogowym","text":"Підняті шлагбауми не звільняють від обов'язку переконатися, що потяг не наближається. Пристрої безпеки бувають несправні, а відповідальність за в'їзд завжди на водієві."},"13623":{"law":"art. 28 ust. 1 Prawa o ruchu drogowym","text":"Наближаючись до переїзду, спостерігають за сигналізацією, шлагбаумами, звуковими сигналами і самою колією в обидва боки. Потяг не встигне загальмувати, тож усе переконання лягає на водія."},"13684":{"text":"Розважливість це посилення уваги там, де небезпека реальна, тобто біля пішохідного переходу. Постійна їзда на максимальному ліміті ігнорує змінні умови, а максимальні прискорення небезпеки не зменшують."},"13769":{"law":"art. 24 ust. 2 Prawa o ruchu drogowym","text":"Інтервал щонайменше 1 метр діє при обгоні, а не при роз'їзді. Роз'їзд це проїзд повз зустрічний транспорт, і там потрібен просто безпечний інтервал."},"13834":{"law":"art. 24 ust. 2 Prawa o ruchu drogowym","text":"На електросамокат поширюється те саме правило, що й на велосипед: при обгоні щонайменше 1 метр інтервалу. Самокат легко втрачає стійкість на нерівності, тож близький проїзд може його перекинути."},"13835":{"law":"art. 20 ust. 6 pkt 2 Prawa o ruchu drogowym","text":"Електросамокат може рухатися щонайбільше 20 км/год, незалежно від того, скільки здатен розвинути. На пішохідній доріжці для нього додатково діє швидкість, близька до пішохідної."},"13850":{"law":"art. 19 ust. 1 i art. 28 ust. 1 Prawa o ruchu drogowym","text":"Злива чи хуртовина скорочують видимість саме там, де треба помітити потяг. Тому перед переїздом знижують швидкість більше, ніж зазвичай, щоб устигнути роздивитися і зупинитися."},"13859":{"law":"art. 24 ust. 1 Prawa o ruchu drogowym","text":"Перед кожним обгоном треба переконатися, що вистачає видимості й місця і що маневр нікому не завадить. Це безумовна вимога, незалежна від типу дороги і часу доби."},"13862":{"law":"art. 24 ust. 7 pkt 3 Prawa o ruchu drogowym","text":"У населеному пункті обгін транспорту з переважним правом проїзду заборонений. Він будь-якої миті може змінити траєкторію чи різко прискоритися, а перехожі дивляться на нього, а не на тебе."},"13863":{"law":"art. 24 ust. 1 Prawa o ruchu drogowym","text":"Обгін завжди вимагає особливої обережності, бо ти виїжджаєш на смугу, якою не рухався, і втрачаєш частину огляду. Це найаварійніший маневр у дорожньому русі."},"13866":{"law":"art. 24 ust. 2 Prawa o ruchu drogowym","text":"На колону пішоходів поширюється те саме правило, що й на одного пішохода: при обгоні щонайменше 1 метр. Колона займає більше місця, і її край будь-якої миті може зміститися."},"13880":{"law":"art. 33a ust. 3 Prawa o ruchu drogowym","text":"Буксирувати один електросамокат іншим заборонено. Обидва стають некерованими, а гальмування одного викидає інший із траєкторії."},"13882":{"law":"art. 135 ust. 1 pkt 1 Prawa o ruchu drogowym","text":"За порушення, яким створено серйозну загрозу безпеці, суд може призначити заборону керування, а поліцейський вилучити посвідчення. Значення має наслідок, а не лише сам факт перевищення ліміту."},"13883":{"law":"art. 19 ust. 1 Prawa o ruchu drogowym","text":"Безпечна швидкість випливає з умов, а не зі знака: на обледенілій дорозі безпечними бувають 30 км/год там, де дозволено 90. Дотримання ліміту саме собою не робить швидкість безпечною."},"13884":{"text":"Так, це стандартна санкція: перевищення більш ніж на 50 км/год у населеному пункті коштує 3 місяці без посвідчення. До цього додається великий штраф і бали."},"13885":{"law":"art. 19 ust. 2 pkt 2 Prawa o ruchu drogowym","text":"Їзда безпідставно повільно заборонена, бо блокує рух і провокує ризикований обгін. На швидкісній дорозі повільне авто буває так само небезпечним, як і розігнане."},"13886":{"text":"Паркувальна картка дає пільги в паркуванні й дозволяє не дотримуватися окремих заборонних знаків, але не підвищує ліміт швидкості. Норм про швидкість не змінює жоден документ."},"13891":{"law":"art. 39 ust. 2 Prawa o ruchu drogowym","text":"Від обов'язку пристібатися звільнена, зокрема, особа з інвалідністю, яку перевозять у візку. Відчуття незручності від паса жодним звільненням не є."},"13893":{"law":"art. 66 ust. 1 Prawa o ruchu drogowym","text":"Транспортний засіб допускають до руху, якщо він утримується так, що не загрожує ні тим, хто в ньому, ні іншим учасникам руху. Кондиціонер і тоновані шибки до допуску стосунку не мають."},"13902":{"law":"art. 19 ust. 3 Prawa o ruchu drogowym","text":"На автомагістралі дистанція це щонайменше половина показника спідометра в метрах, тобто на 140 км/год аж 70 метрів, а не 60. Правило просте: поділи швидкість навпіл."},"13903":{"law":"art. 19 ust. 3 Prawa o ruchu drogowym","text":"На двопроїзній швидкісній дорозі дозволено 120 км/год, тож дистанція щонайменше 60 метрів, а не 50. Завжди рахують половину показника спідометра."},"13904":{"law":"art. 19 ust. 3 Prawa o ruchu drogowym","text":"Правило половини швидкості діє на автомагістралі й двопроїзній швидкісній дорозі та не застосовується під час обгону. Інакше маневр було б неможливо виконати взагалі."},"13909":{"text":"Зношений протектор відводить значно менше води, ніж новий, тож шина раніше втрачає контакт з асфальтом. При залишковому протекторі аквапланування починається на швидкості, за якої нова шина ще тримає."},"13910":{"text":"При рясному дощі між шиною й асфальтом утворюється шар води, і авто перестає реагувати на кермо та гальма. Це і є аквапланування, і воно закінчується втратою керування."},"13911":{"law":"art. 19 ust. 1 Prawa o ruchu drogowym","text":"Ліміт це верхня межа, а не гарантія безпеки: у тумані чи ожеледицю навіть швидкість у межах норми буває завеликою. Обов'язок контролювати авто діє незалежно від знаків."},"13912":{"law":"art. 19 ust. 1 Prawa o ruchu drogowym","text":"Норма прямо називає, зокрема, інтенсивність руху, поряд із рельєфом, станом і видимістю дороги, станом транспорту та погодними умовами. Прогнозу погоди й власного досвіду в цьому переліку немає."},"13915":{"text":"На великій швидкості погляд фокусується далеко попереду, і поле зору різко звужується. Саме тому водій на швидкій дорозі перестає помічати узбіччя і бічні виїзди."},"13916":{"law":"art. 26 ust. 6 Prawa o ruchu drogowym","text":"Щодо особи з видимо обмеженою рухливістю обов'язок зупинитися є безумовним і діє також поза переходом. Тут немає місця для оцінки, чи встигне вона перейти."},"13917":{"text":"Місце для особи з інвалідністю ширше саме для того, щоб можна було відчинити двері й виїхати візком. Зайняти навіть його частину означає звести нанівець увесь сенс такого місця."},"13918":{"text":"Відцентрова сила зростає пропорційно квадрату швидкості, тож у повороті будь-яке прискорення виштовхує авто назовні. Коли вона перевищить зчеплення шин, машина зійде з траєкторії."},"13919":{"text":"Подвоєння швидкості в повороті збільшує відцентрову силу вчетверо, бо вона залежить від квадрата швидкості. Тому невелике додавання газу в повороті дає значно більшу різницю, ніж здається."},"13920":{"text":"Колеса вантажівки викидають убік стіну води, яка на мить повністю закриває лобове скло. Тому перед роз'їздом знижують швидкість і вмикають двірники на максимум."},"13921":{"text":"Руки на кермі мають бути злегка зігнуті в ліктях: лише тоді можна повністю провернути кермо, не відриваючи спину від спинки. Випрямлені руки забирають точність, а сильно зігнуті силу."},"13923":{"text":"Підголівник на рівні потилиці обмежує різкий закид голови при ударі ззаду і захищає шийний відділ хребта. Опущений до рівня шиї підголівник сам стає важелем."},"13924":{"text":"Погано підібрана посадка ускладнює керування: надто відсунуте сидіння не дає вичавити зчеплення до кінця, а надто близьке блокує рух рук. Налаштування добирають індивідуально, а не лише в крайніх положеннях."},"13925":{"text":"Регулювання сидіння визначає, чи дістанеш до педалей і чи зможеш повністю провернути кермо, а також як спрацюють пас і подушка. Це елемент безпеки, а не питання зручності."},"13926":{"law":"art. 19 ust. 1 Prawa o ruchu drogowym","text":"Самої швидкості замало: важать також радіус повороту, стан і нахил покриття, завантаження авта і видимість за поворотом. Поворот проходять за тим, що видно, а не за спідометром."},"13927":{"text":"Безпечне проходження повороту починається до нього: гальмуєш на прямій, обираєш траєкторію і лише тоді повертаєш. Траєкторію добирають так, щоб якнайдовше бачити вихід із повороту."},"13928":{"text":"Одна рука на кермі не покращує точність, а забирає її: неможливо ні швидко повернути кермо назад, ні зреагувати на ривок. Кермо тримають обома руками, у положенні на дев'яту і третю годину."},"13929":{"text":"Рука, просунута всередину керма, отримує удар подушкою, що спрацьовує, і втрачає контакт із кермом при ривку. Це стосується будь-якої ситуації, а не лише паркування."},"13932":{"law":"art. 135 ust. 1 pkt 1a Prawa o ruchu drogowym","text":"Так, при перевищенні більш ніж на 50 км/год у населеному пункті поліцейський вилучає посвідчення на місці, під квитанцію. Квитанція дозволяє їхати ще 24 години."},"13936":{"law":"art. 19 ust. 1 Prawa o ruchu drogowym","text":"Ліміт каже лише, скільки щонайбільше можна, а не скільки безпечно саме зараз. У тумані, на мокрому асфальті чи в заторі швидкість, що забезпечує контроль, значно нижча."},"13941":{"law":"art. 4 i art. 45 Prawa o ruchu drogowym","text":"Побачивши небезпечну поведінку на дорозі, попереджаєш інших, наприклад аварійними вогнями, і за можливості усуваєш загрозу. Принцип обмеженої довіри діє в обидва боки: передбачаєш і попереджаєш."},"13942":{"law":"art. 2 pkt 47b Prawa o ruchu drogowym","text":"За визначенням електросамокат не має сидіння, їзда відбувається стоячи. Транспорт із сидінням це вже інша категорія, наприклад мопед, і на нього поширюються інші норми."},"13943":{"law":"art. 4 Prawa o ruchu drogowym","text":"Попередження дає іншим час зреагувати й може запобігти наступним подіям, наприклад наїзду на розлиту оливу. Проте воно не звільняє від відповідальності й не гарантує, що нічого не станеться."},"13944":{"law":"art. 3a ust. 2 ustawy o kierujących pojazdami","text":"Поза житловою зоною електросамокатом може керувати особа від 10 років, яка має велосипедну картку. Із 18 років жодного документа вже не потрібно, а в житловій зоні віку не вимагають."},"13945":{"text":"Страховики враховують історію порушень, тож штрафи за швидкість підвищують внесок ОЦВ при поновленні. Втрата знижок буває відчутнішою за сам штраф."},"13950":{"text":"Інвалідність не означає, що людина порушить правила, і такого припущення не роблять. Натомість треба зважати, що така особа може потребувати більше часу і не встигне відійти."},"13951":{"law":"art. 24 ust. 2 Prawa o ruchu drogowym","text":"При обгоні електросамоката діє щонайменше 1 метр, а не 0,5 метра. Та сама відстань стосується велосипеда, мопеда, мотоцикла і пішохода."},"13962":{"law":"art. 24 ust. 2 Prawa o ruchu drogowym","text":"Пристрій для пересування, як-от ролики чи скейтборд, підпадає під те саме правило: щонайменше 1 метр при обгоні. Людина на такому пристрої ще менш стійка, ніж велосипедист."},"13975":{"law":"art. 26 ust. 3 pkt 2 Prawa o ruchu drogowym","text":"На нерегульованому пішохідному переході й безпосередньо перед ним обгін заборонений. Той, хто обганяє, закриває огляд: ані він не бачить пішохода, ані пішохід його."},"13976":{"law":"art. 26 ust. 3 pkt 2 Prawa o ruchu drogowym","text":"Заборона стосується нерегульованих переходів, тож там, де рухом керує світлофор або поліцейський, обгін допустимий. Сигналізація розділяє рух пішоходів і транспорту в часі."},"13985":{"law":"art. 26 ust. 1 Prawa o ruchu drogowym","text":"Особа, яка веде пристрій для пересування, вважається пішоходом, тож, ступаючи на перехід, має перевагу. Ведення велосипеда чи самоката поруч статусу пішохода не змінює."},"13986":{"law":"art. 26 ust. 1 Prawa o ruchu drogowym","text":"Щодо пішохода, який перебуває на переході, діють особлива обережність і обов'язок поступитися. Особа, яка веде пристрій для пересування, прирівнюється до будь-якого іншого пішохода."},"13987":{"law":"art. 51 ust. 3 Prawa o ruchu drogowym","text":"Дальнє світло не можна вмикати, якщо воно може засліпити будь-кого, зокрема пішоходів у колоні. Засліплена колона втрачає орієнтацію і може зійти на проїзну частину."},"13991":{"law":"art. 26 ust. 6 Prawa o ruchu drogowym","text":"Спеціальний знак, тобто біла тростина чи пов'язка з трьома крапками, позначає незрячу людину. Щодо неї обов'язок зупинитися діє всюди, зокрема й поза переходом."},"13992":{"law":"art. 26 ust. 6 Prawa o ruchu drogowym","text":"Особа з видимо обмеженою рухливістю має право перейти, а водій зобов'язаний зупинитися. Норма не вимагає ні пішохідного переходу, ні жодного документа."},"13993":{"text":"Рекомендований перехід не є пішохідним переходом у розумінні правил, тож переваги там немає. Це, однак, не звільняє від обережності, бо пішохід усе одно може там вийти на дорогу."},"13994":{"law":"art. 4 Prawa o ruchu drogowym","text":"Рекомендований перехід виглядає як місце для переходу, тож пішохід часто виходить там без вагань. Принцип обмеженої довіри велить припустити саме це і завчасно знизити швидкість."},"13995":{"law":"art. 23 ust. 1 pkt 1 Prawa o ruchu drogowym","text":"Роз'їжджаючись із пішоходом, треба за потреби взяти праворуч, знизити швидкість і навіть зупинитися. На вузькій дорозі пішоходу нікуди подітися, тож поступається водій."},"14002":{"law":"art. 26 ust. 1 Prawa o ruchu drogowym","text":"Особа, яка веде пристрій для пересування, це пішохід, а пішохід, що ступає на перехід, має перевагу. Водій зобов'язаний поступитися, а не оцінювати, чи встигне проскочити."},"14007":{"law":"art. 4 i art. 45 Prawa o ruchu drogowym","text":"Розлита олива це смертельна пастка передусім для мотоциклістів, тож треба попередити інших і викликати служби. Поїхати геть і промовчати означає покинути небезпеку, яку сам створив."},"14015":{"law":"art. 19 ust. 1 Prawa o ruchu drogowym","text":"Втома, хвороба чи стрес подовжують час реакції, тож безпечна швидкість для того самого водія змінюється день у день. Після нічної зміни вона нижча, ніж після відпочинку."},"14062":{"law":"art. 102 ust. 1d ustawy o kierujących pojazdami","text":"Керування попри подовжене до шести місяців затримання закінчується анулюванням права керування на 5 років. Після цього посвідчення доводиться здобувати заново, з усіма іспитами."},"14063":{"law":"art. 102 ust. 1d ustawy o kierujących pojazdami","text":"Наслідок той самий, незалежно від того, за що забрали посвідчення: анулювання права керування на 5 років. Значення має те, що водій керував попри чинну заборону."},"14064":{"law":"art. 135 ust. 1 pkt 2 Prawa o ruchu drogowym","text":"Посвідчення забирають, коли кількість перевезених осіб перевищує кількість місць більш ніж на дві, тобто на три і більше. Одна чи дві особи понад норму це штраф і бали, але без втрати документа."},"14107":{"law":"art. 33b ust. 2 Prawa o ruchu drogowym","text":"Пішохідним переходом не можна їхати вздовж на пристрої персонального транспорту, його переходять пішки, ведучи пристрій. Перехід призначений для переходу, а не для проїзду."},"1864":{"law":"art. 6 ust. 1 pkt 3 ustawy o kierujących pojazdami","text":"Квадроцикл, який не є легким (до 400 кг, двигун понад 15 кВт), потребує категорії B1. Категорія AM охоплює лише легкі квадроцикли, а категорія A стосується мотоциклів."},"1866":{"law":"art. 81 Prawa o ruchu drogowym","text":"Власник зобов'язаний проходити періодичний технічний огляд. Страхування від нещасних випадків і каско добровільні, обов'язковим є лише ОЦВ."},"1876":{"text":"Тиск перевіряють на холодних шинах безпосередньо перед поїздкою. Після їзди шини нагріті й показник завищений, а за добу тиск ще може змінитися."},"1877":{"law":"art. 61 Prawa o ruchu drogowym","text":"Вантаж не може порушувати стійкість транспортного засобу. Він також не повинен закривати ліхтарі чи номерні знаки, і його завжди треба закріпити від зміщення."},"1878":{"law":"art. 61 ust. 1 Prawa o ruchu drogowym","text":"Вантаж завжди закріплюють від зміщення. Мала швидкість нічого не змінює, бо достатньо одного гальмування чи повороту, щоб вантаж зрушив."},"1879":{"law":"art. 61 ust. 2 Prawa o ruchu drogowym","text":"Сипкий вантаж перевозять у щільному кузові, накритим так, щоб нічого не висипалося на дорогу. Сама лише мала швидкість чи борти цього не забезпечують."},"1880":{"law":"art. 61 ust. 1 Prawa o ruchu drogowym","text":"Кріплення має бути зафіксоване так, щоб не послабилося під час руху. Ремінь, що звисає, може намотатися на колесо або зачепити інший транспортний засіб."},"1881":{"law":"art. 61 ust. 3 Prawa o ruchu drogowym","text":"Вантаж не може обмежувати водієві оглядовість дороги. Він також не повинен закривати ліхтарі, світлоповертачі чи номерні знаки, навіть частково."},"1882":{"text":"Найважчі речі кладуть якомога нижче, глибше і по центру. Вага зверху або ззаду піднімає центр ваги й погіршує стійкість авто в повороті та під час гальмування."},"1883":{"law":"art. 61 ust. 3 Prawa o ruchu drogowym","text":"Вантаж на причепі не може закривати його ліхтарі. Його також розподіляють рівномірно, бо зсунутий убік або назад вантаж псує стійкість автопоїзда."},"1888":{"law":"art. 60 ust. 2 pkt 4 Prawa o ruchu drogowym","text":"Заборонено буксирувати за транспортним засобом особу на лижах, санках чи роликах. Рація CB дозволена, а дитину в кріслі можна возити спереду після вимкнення подушки безпеки."},"1905":{"text":"Вогнегасник має бути закріплений і в межах досяжності водія, наприклад під сидінням. Незакріплений вогнегасник під час гальмування стає снарядом, а із задньої полиці його швидко не дістати."},"2025":{"text":"ASR це система контролю тяги: вона протидіє пробуксовуванню ведучих коліс під час рушання та розгону. Блокуванням коліс під час гальмування опікується ABS."},"2026":{"text":"ESP стабілізує траєкторію, коли авто починає зносити або заносити в повороті. За блокування коліс відповідає ABS, а за пробуксовування під час рушання ASR."},"2161":{"text":"Якщо стерильної пов'язки немає, візьми чистий одяг потерпілого і притисни рану. При кровотечі зволікання небезпечніше за нестерильний матеріал."},"2164":{"text":"Тиснучу пов'язку накладають при кровотечі, щоб спинити витікання крові. При розчавленні кінцівки та при виділеннях із вуха тиск не застосовують."},"2535":{"text":"У дощ передусім знижуй швидкість: зростає гальмівний шлях і ризик аквапланування. Вимкнення контролю тяги і їзда в колії лише погіршують ситуацію."},"2536":{"text":"Потрапивши в колію з водою, знижуй швидкість плавно, без різких рухів. Різке гальмування чи прискорення при аквоплануванні закінчується втратою керування."},"2538":{"text":"На засніженій дорозі безпеку підвищують зимові шини, бо вони чіпляються за низької температури. Ручне гальмо блокує задню вісь, а різкий розгін спричиняє пробуксовування."},"3187":{"text":"Наркотики в жодній кількості не покращують оцінку ризику. Вони подовжують час реакції, спотворюють оцінку відстані та швидкості й дають оманливе відчуття впевненості."},"3232":{"text":"Алкоголь звужує поле уваги, тому розподіл уваги погіршується і робити дві справи одночасно важче. Саме тому водій напідпитку не помічає пішохода, дивлячись на світлофор."},"3340":{"text":"Плавне рушання це поступове відпускання зчеплення з легким додаванням газу. Різке відпускання педалі глушить двигун або смикає авто."},"3353":{"law":"art. 45 ust. 2 pkt 1 Prawa o ruchu drogowym","text":"Заборонено користуватися телефоном, якщо це вимагає тримати слухавку чи мікрофон у руці. Гучномовний комплект дозволений, круїз-контроль у населеному пункті теж."},"3429":{"text":"У тумані вночі передусім знижуй швидкість. Дальнє світло відбивається від крапель води і засліплює, а їзда впритул за попереднім авто не лишає місця для гальмування."},"352":{"law":"art. 22 ust. 6 pkt 4 Prawa o ruchu drogowym","text":"Знак D-3 позначає дорогу з одностороннім рухом, а на такій дорозі розворот заборонений. Розвернувшись, ти б їхав назустріч потоку, просто на автомобілі, яким нікуди подітися."},"3523":{"text":"Через велику калюжу проїжджають, плавно знизивши швидкість. Різке гальмування чи прискорення на воді відриває шини від покриття."},"3573":{"law":"art. 44 ust. 2 Prawa o ruchu drogowym","text":"Свідок ДТП зобов'язаний зупинитися, викликати медичну допомогу і надати першу допомогу. Цей обов'язок не залежить від того, хто спричинив пригоду."},"3625":{"law":"art. 23 ust. 1 pkt 1 Prawa o ruchu drogowym","text":"Під час роз'їзду закон вимагає безпечного інтервалу, а не конкретної кількості метрів. Безпечний інтервал залежить від ширини проїзної частини, швидкості та умов руху."},"3626":{"law":"art. 24 ust. 2 Prawa o ruchu drogowym","text":"Єдиний інтервал, заданий у метрах, стосується обгону велосипеда, мопеда, мотоцикла і пішохода: щонайменше 1 метр. Для інших маневрів діє безпечний інтервал."},"3627":{"law":"art. 23 ust. 1 pkt 1 Prawa o ruchu drogowym","text":"Під час об'їзду перешкоди діє безпечний інтервал, що залежить від ширини проїзної частини та умов руху. Конкретної кількості метрів закон тут не наводить."},"3628":{"law":"art. 24 ust. 2 Prawa o ruchu drogowym","text":"Під час обгону легкового авто діє безпечний інтервал, що залежить від ширини проїзної частини та умов руху. Жорсткий 1 метр стосується лише велосипеда, мопеда, мотоцикла і пішохода."},"3629":{"law":"art. 24 ust. 2 Prawa o ruchu drogowym","text":"Обганяючи мотоцикл, треба тримати інтервал не менше 1 метра. Те саме правило стосується велосипеда, мопеда і пішохода."},"3630":{"law":"art. 24 ust. 2 Prawa o ruchu drogowym","text":"Колону пішоходів обганяють з інтервалом не менше 1 метра, так само як окремого пішохода чи велосипедиста."},"3634":{"text":"Гальмівний шлях зростає пропорційно квадрату швидкості, тож удвічі швидше означає вчетверо довший шлях. Із 50 до 100 км/год гальмування подовжується вчетверо, а не вдвічі."},"3650":{"law":"art. 19 ust. 3a Prawa o ruchu drogowym","text":"Поза населеним пунктом у тунелі, довшому за 500 метрів, легковик тримає дистанцію щонайменше 50 метрів. Транспорт понад 3,5 тонни тримає 80 метрів."},"3651":{"text":"Зупинковий шлях це шлях реакції плюс гальмівний шлях, тож час реакції водія впливає на нього прямо. Маса пасажирів у легковику в цьому розрахунку незначна."},"3652":{"text":"На зупинковий шлях прямо впливають швидкість і стан покриття, бо від них залежать зчеплення та енергія, яку треба погасити. Маса пасажира незначна."},"3658":{"law":"art. 44 ust. 2 Prawa o ruchu drogowym","text":"Обов'язок надати допомогу не залежить від медичної кваліфікації. Достатньо зробити те, що вмієш: убезпечити місце, викликати допомогу і виконати базові рятувальні дії."},"3723":{"text":"Обов'язковим оснащенням легковика в Польщі є знак аварійної зупинки і вогнегасник. Аптечка та запасне колесо рекомендовані, але законом не вимагаються."},"3724":{"text":"Вогнегасник належить до обов'язкового оснащення легковика разом зі знаком аварійної зупинки. Аптечка і запасне колесо не обов'язкові."},"3759":{"law":"art. 30 ust. 1 i 3 Prawa o ruchu drogowym","text":"У тумані дозволено вмикати передні протитуманні фари, замість ближнього світла або разом із ним. Дальнє світло відбивається від туману і засліплює, а самих денних вогнів недостатньо."},"3761":{"law":"art. 30 ust. 3 Prawa o ruchu drogowym","text":"У тумані поза населеним пунктом під час обгону водій зобов'язаний подавати короткочасні звукові сигнали. Задні протитуманні ліхтарі вмикають лише за видимості менше 50 метрів."},"3778":{"text":"Роз'їжджаючись уночі, дивись праворуч від фар зустрічного авта і стеж там за узбіччям. Погляд прямо у світло засліплює на кілька секунд, а перемикання на дальнє засліплює іншого водія."},"3781":{"text":"Ксенон не можна ставити у фару, розраховану на галогенну лампу. Тоді фара розсіює світло поза межами омологації та засліплює інших водіїв, навіть якщо цоколь підходить."},"3783":{"law":"art. 45 ust. 2 pkt 1 Prawa o ruchu drogowym","text":"Користуватися навігацією під час руху дозволено. Заборонено відстібати пас безпеки і користуватися телефоном, який треба тримати в руці."},"3784":{"text":"Мінімальна глибина протектора 1,6 міліметра. Нижче цього шина перестає відводити воду і різко зростає ризик аквапланування."},"3785":{"text":"Перегорілий покажчик повороту це несправність освітлення: інші водії не бачать твого наміру. Брудний фільтр і перегріті свічки псують динаміку, але не позбавляють безпеки руху."},"3856":{"text":"Замалий тиск на педаль не використовує зчеплення шин і подовжує гальмівний шлях. Блокування коліс і втрата керованості це наслідок надто сильного тиску в авто без ABS."},"3857":{"text":"Без ABS надто сильне гальмування блокує колеса, а заблоковані колеса не керують авто. Кермо перестає діяти, і машина ковзає прямо."},"3858":{"text":"В авто з ABS гальмують швидко і сильно, а система сама стежить, щоб колеса не заблокувалися. Переривчасте натискання лише заважає ABS, бо повторює те, що він робить краще."},"3859":{"text":"Пульсація педалі означає, що ABS працює, тож тримай тиск до кінця гальмування. Послаблення зусилля подовжує гальмівний шлях, а відпускання педалі взагалі його припиняє."},"3860":{"text":"ABS не дає колесам заблокуватися, тож авто лишається керованим навіть коли гальмуєш у бічному заносі. Він працює завжди, а не лише на прямій чи лише в повороті."},"3861":{"text":"На підйомі, якщо відпустити ручне гальмо до того, як зчеплення почне передавати тягу, авто скотиться назад. Гальмо відпускають лише тоді, коли відчутно, що машина рушає."},"3882":{"text":"Червона лампа гальмівної системи означає несправність гальм, тож треба зупинитися і перевірити рівень рідини. Продовження руху може закінчитися відмовою гальм."},"3885":{"text":"Червона лампа системи охолодження попереджає, що охолоджувальна рідина перегріта. Треба зупинитися і дати двигуну охолонути, бо перегрів закінчується серйозною поломкою."},"3889":{"text":"Плями рідин на місці стоянки свідчать про негерметичність системи, наприклад гальмівної чи охолодження. Безбарвні вихлопні гази це норма, як і лампа заряду до запуску двигуна."},"3890":{"text":"Чорний або синій густий дим означає, що двигун спалює забагато пального чи оливи. Безбарвні гази це норма, а лампа тиску оливи до запуску двигуна горить завжди."},"3891":{"text":"Докаткою можна користуватися недовго і з обмеженою швидкістю, саме для цього вона й потрібна. Зношені колодки чи диски та пошкоджені амортизатори виключають авто з руху."},"4160":{"law":"art. 30 ust. 1 pkt 2 Prawa o ruchu drogowym","text":"За видимості менше 50 метрів можна ввімкнути задні протитуманні ліхтарі, щоб ті, хто їде позаду, помітили авто раніше. Дальнє світло відбивається від туману, а скорочення дистанції прямо небезпечне."},"4362":{"text":"Найслизькіше на початку дощу, коли вода змішується з пилом і оливою на дорозі. Після тривалого дощу цей шар змивається і зчеплення частково повертається."},"4364":{"text":"Що швидше їдеш, то вужчим стає кут зору: погляд фокусується на точці далеко попереду. Тому на великій швидкості легко не помітити пішохода або транспорт збоку."},"4367":{"text":"Поле зору обмежує засліплення фарами зустрічних автомобілів: оку потрібно кілька секунд, щоб відновитися. Салонне дзеркало і кондиціонер видимості не забирають."},"4368":{"text":"Неправильно відрегульовані фари освітлюють закороткий відрізок дороги або світять убік, тож уночі просто не видно того, що попереду. Регулювання перевіряють на техогляді."},"4369":{"text":"Алкоголь звужує поле зору до так званого тунельного бачення, тож водій перестає помічати те, що збоку. Кліпання і перерва на відпочинок діють навпаки, вони покращують увагу."},"4370":{"text":"Сидіння, виставлене надто низько чи високо, забирає частину огляду: стійки й капот тоді закривають більше, ніж мали б. Сонцезахисні окуляри в сонячний день допомагають, а не заважають."},"4371":{"text":"Зі зростанням швидкості кут зору звужується, бо погляд фокусується дедалі далі попереду. На 50 км/год бачиш широко, на 130 км/год практично лише вузький коридор."},"4374":{"text":"На кожній передачі розганяйся настільки, щоб після переходу на вищу двигун не задихався і не смикався. Крутити до відсічки це витрата пального, а перескакувати через дві передачі душить двигун."},"4375":{"law":"art. 61 ust. 3 Prawa o ruchu drogowym","text":"Велосипеди можна возити на даховому багажнику, бо там вони не закривають ні ліхтарі, ні номерний знак. Задній тримач дозволений лише тоді, коли знак і ліхтарі лишаються видимими."},"4472":{"law":"art. 81 Prawa o ruchu drogowym","text":"Технічний огляд має значення протягом усього часу використання авто, бо гальма, підвіска й світло зношуються незалежно від гарантії. Гарантія стосується ремонтів, а не безпеки руху."},"4495":{"text":"ABS не дає колесам заблокуватися під час гальмування, завдяки чому авто лишається керованим і стійким. Проте він не рятує від заносу за будь-якої швидкості й не допомагає в поворотах."},"4534":{"text":"На снігу все роблять плавно, без різких рухів кермом, бо зчеплення мінімальне. Вимкнення контролю тяги і розгін на підйомі закінчуються пробуксовуванням і заносом."},"4562":{"law":"art. 162 Kodeksu karnego","text":"Відповідає кожен, хто міг допомогти, не наражаючи себе чи інших на втрату життя або тяжку шкоду здоров'ю. Обов'язок не обмежується лікарями чи учасниками пригоди."},"4563":{"text":"Потерпілого витягують з авта лише тоді, коли інакше не врятувати життя, наприклад при зупинці кровообігу чи пожежі. Без такої потреби переміщення загрожує додатковою травмою хребта."},"4578":{"text":"Диспетчеру передусім потрібно знати, де сталася пригода та скільки потерпілих і в якому вони стані. Від цього залежить, скільки і яких бригад він відправить."},"4579":{"text":"Одяг, що горить, гасять, поклавши людину на землю і придушивши вогонь курткою чи ковдрою, щоб перекрити доступ повітря. Порошковий вогнегасник додатково пошкоджує дихальні шляхи й обпечену шкіру."},"4592":{"text":"Без справних стоп-сигналів той, хто їде позаду, не знає, що ти гальмуєш, тож користуватися авто не можна. Парктроніки й кондиціонер на безпеку руху не впливають."},"4593":{"text":"Червона лампа тиску оливи означає, що двигун працює без змащення, тож зупинись і негайно заглуши його. Кільканадцять секунд подальшої їзди можуть заклинити двигун."},"4600":{"text":"112 це спільний номер екстреного виклику: він з'єднує зі швидкою, пожежними і поліцією одночасно. Працює по всій Польщі та в усьому Євросоюзі, навіть із телефона без SIM-картки."},"469":{"text":"Горять разом червоний і жовтий, а це сигнал, що зараз увімкнеться зелений. Рушати ще не можна, але можна підготувати авто до руху."},"475":{"law":"sygnalizator S-2, rozporządzenie w sprawie znaków i sygnałów drogowych","text":"Поряд із червоним світиться зелена стрілка умовного повороту праворуч. Вона дозволяє поворот лише після зупинки перед світлофором і поступання всім, зокрема пішоходам на переході."},"477":{"law":"sygnalizator kierunkowy S-3, rozporządzenie w sprawie znaków i sygnałów drogowych","text":"Для твоєї смуги горить напрямний світлофор із зеленою стрілкою ліворуч. Такий сигнал дозволяє рух лише в напрямку стрілки, тобто поворот ліворуч, але не розворот."},"478":{"law":"sygnalizator kierunkowy S-3, rozporządzenie w sprawie znaków i sygnałów drogowych","text":"Зелена стрілка праворуч світиться на місці зеленого сигналу, тобто це напрямний світлофор. Напрямна сигналізація безконфліктна: рухаючись у вказаному напрямку, ти не перетнешся з іншим потоком, зокрема з пішоходами."},"480":{"text":"Для твоєї смуги горить червоний сигнал, а він беззастережно забороняє в'їзд за світлофор. Зупинитися треба перед світлофором або перед стоп-лінією."},"486":{"law":"sygnalizator kierunkowy S-3, rozporządzenie w sprawie znaków i sygnałów drogowych","text":"Напрямний світлофор показує зелену стрілку вгору, тож дозволяє лише рух прямо. Поворот праворуч заборонений незалежно від того, чи завадив би він комусь."},"544":{"law":"art. 22 ust. 1 i 4 Prawa o ruchu drogowym","text":"Смуги розділяє переривчаста лінія, тож зміна смуги дозволена. Треба лише показати маневр покажчиком повороту і поступитися транспорту, що вже рухається смугою, на яку ти перестроюєшся."},"589":{"text":"Під знаком дороги з одностороннім рухом висить табличка, що виключає велосипеди, а вздовж лівого краю йде смуга з символом велосипеда. Це велосипедний контрарух: велосипедисти законно їдуть тут назустріч."},"591":{"text":"Смугу ліворуч відділяє суцільна жовта лінія, тобто тимчасове розмічення з часів дорожніх робіт. Жовте розмічення має перевагу над білим, а суцільну лінію перетинати не можна."},"627":{"text":"Вісь проїзної частини позначена подвійною лінією: з твого боку суцільна, з протилежного переривчаста. Таку лінію дозволено перетинати лише з того боку, де вона переривчаста, тож тобі не можна."},"6318":{"text":"Алкоголь змінює поле зору: звужує його і послаблює периферійний зір та оцінку відстані. Водій дивиться прямо перед собою і не помічає пішохода, який виходить збоку."},"6340":{"text":"Подушка безпеки зменшує травми, але не захищає повністю і працює лише разом із застебнутим пасом. Кузов авта вона не захищає взагалі, для цього є зони деформації."},"6361":{"law":"art. 51 ust. 3 Prawa o ruchu drogowym","text":"Дальнє світло не можна вмикати, коли назустріч їде інший транспорт, бо воно засліплює його водія. Дощ і в'їзд у місто самі собою такого обов'язку не створюють."},"6362":{"law":"art. 51 ust. 3 Prawa o ruchu drogowym","text":"На ближнє світло перемикаються завжди, коли можна засліпити водія попереду, зокрема через його дзеркала. Сам вигляд авта далеко попереду обов'язку ще не створює."},"6378":{"text":"Правильно виставлене зовнішнє дзеркало показує зону позаду авта і вузьку смужку його борту, яка слугує орієнтиром. Самого лише борту чи лише сусідньої смуги замало."},"6442":{"text":"Габаритні вогні показують іншим, де стоїть чи їде транспортний засіб і яка його ширина. Дорогу вони не освітлюють, а для зміни смуги є покажчики повороту."},"6443":{"text":"Фари, виставлені зависоко, світять в очі зустрічним водіям. На витрату пального чи ламп регулювання фар не впливає."},"6451":{"text":"Фари, виставлені занизько, освітлюють лише кілька метрів перед авто, тож уночі дорогу видно значно гірше. На витрату пального і ламп вони не впливають."},"6463":{"text":"Переохолодженій людині виклич допомогу, перенеси в тепле місце, вкрий і зігрівай повільно. Гарячий напій і алкоголь розширюють судини шкіри та прискорюють втрату тепла з ядра тіла."},"7445":{"law":"art. 60 ust. 2 pkt 4 Prawa o ruchu drogowym","text":"Буксирувати за автомобілем дітей на санках заборонено. Легкий причіп дозволений, а буксирування іншого авта в населеному пункті теж."},"7446":{"law":"art. 19 ust. 3b Prawa o ruchu drogowym","text":"Стоячи в заторі в тунелі, треба лишити щонайменше 5 метрів до попереднього автомобіля. Цей проміжок потрібен рятувальним службам для проїзду й дозволяє виїхати, якщо спалахне пожежа."},"7447":{"law":"art. 45 ust. 2 pkt 1 Prawa o ruchu drogowym","text":"Заборонено розмовляти по телефону, тримаючи його в руці. Радіо і навігація дозволені, якщо користування ними не відволікає увагу від дороги."},"7451":{"law":"art. 61 ust. 8 Prawa o ruchu drogowym","text":"Вантаж, що виступає ззаду, позначають червоним прапорцем або щитком, а в темряві додатково червоним ліхтарем і світлоповертачем. Червоний у дорожньому русі це попереджувальний колір ззаду."},"7452":{"text":"Фактична повна маса причепа не може перевищувати фактичну повну масу автомобіля, що його тягне. Важчий причіп починає керувати авто замість того, щоб бути керованим."},"7454":{"law":"art. 31 ust. 2 pkt 5 Prawa o ruchu drogowym","text":"На автомагістралі буксирування заборонене, крім евакуації спеціальним транспортом до найближчого з'їзду. На швидкісній дорозі та в житловій зоні буксирувати можна."},"7457":{"law":"art. 61 ust. 6 Prawa o ruchu drogowym","text":"Ланцюги ставлять лише на дорогу, вкриту снігом. На голому асфальті вони руйнують покриття і шину, а сама дата чи температура цього не визначають."},"7461":{"text":"Найдовший гальмівний шлях на льоду, бо зчеплення шин там у кілька разів менше, ніж на сухому асфальті. Мокра дорога теж подовжує гальмування, але не так різко."},"7463":{"text":"ABS дозволяє зберегти контроль над авто при різкому гальмуванні, бо колеса не блокуються і кермо продовжує діяти. Гальмівний шлях він скорочує не завжди: на гравії чи снігу може навіть подовжити."},"7465":{"law":"art. 46 ust. 2 Prawa o ruchu drogowym","text":"Автомобіль, залишений на схилі, треба убезпечити від скочування: стоянкове гальмо, увімкнена передача і колеса, повернуті до бордюру. Сама лише передача на крутому підйомі буває недостатньою."},"748":{"law":"art. 24 Prawa o ruchu drogowym","text":"Ти рухаєшся проїзною частиною з двома смугами в цьому напрямку, смуги розділяє переривчаста лінія, сигнал зелений і жодної заборони обгону тут немає. Обганяєш лівою смугою, переконавшись, що вона вільна."},"7512":{"law":"art. 31 ust. 1 pkt 2 Prawa o ruchu drogowym","text":"Буксирований автомобіль позначають світлоповертальним трикутником ззаду ліворуч, а в умовах обмеженої видимості додатково ввімкненим світлом. Самі лише аварійні вогні цього не замінюють."},"7513":{"law":"art. 78 ust. 4 Prawa o ruchu drogowym","text":"Власник зобов'язаний вказати, кому довірив авто, і звільняє його лише ситуація, коли машину використали проти його волі та відома і він не міг цьому запобігти. Ведення підприємницької діяльності від обов'язку не звільняє."},"7515":{"law":"art. 60 ust. 1 pkt 2 Prawa o ruchu drogowym","text":"Їзда з невидимим номерним знаком заборонена, бо автомобіль неможливо ідентифікувати. Закриття знака вантажем не є виправданням, вантаж треба перевозити інакше."},"7516":{"text":"Наліпка з позначенням іншої держави, ніж країна реєстрації, заборонена, бо вводить в оману щодо походження авта. Знак із символом PL тут нічого не змінює."},"7518":{"text":"Швидше блимання контрольної лампи це стандартний сигнал, що одна з ламп покажчика повороту перегоріла. Тож перевіряють лампи, а не акумулятор, бо решта споживачів працює нормально."},"7519":{"text":"Рівень оливи перевіряють на холодному двигуні перед поїздкою або через кілька хвилин після зупинки, коли олива стече в піддон. Вимір одразу після глушіння чи на працюючому двигуні дає занижений результат."},"7708":{"text":"На сухому покритті рушають на першій передачі, бо вона дає найбільшу тягу. Друга передача підходить лише на дуже слизькій дорозі, коли треба зменшити пробуксовування."},"788":{"law":"art. 24 ust. 6 Prawa o ruchu drogowym","text":"Водієві, якого щойно обігнали, не можна збільшувати швидкість під час обгону і безпосередньо після нього. Прискорення в цей момент змушує того, хто обганяє, довше залишатися на зустрічній смузі."},"8320":{"law":"art. 24 ust. 5 Prawa o ruchu drogowym","text":"Рейковий транспорт за загальним правилом обганяють праворуч, але на дорозі з одностороннім рухом це дозволено робити й ліворуч. На односторонній дорозі немає зустрічного руху, тож маневр безпечний."},"891":{"text":"Знак A-1 попереджає про один небезпечний поворот праворуч. Якби поворотів було більше, тут стояв би знак A-3 із двома дугами, а не з однією."},"892":{"text":"Знак A-2 попереджає про один небезпечний поворот ліворуч, а не про кілька. Про серію поворотів інформує знак із двома дугами, тобто A-3 або A-4."},"893":{"text":"Під знаком поворотів висить табличка з цифрою 3, яка вказує, скільки поворотів попереду. Оскільки їх три, відповідь про два повороти хибна."},"894":{"text":"Знак A-4 попереджає про два небезпечні повороти, перший з яких ліворуч. Без таблички з числом знак із двома дугами означає рівно два повороти."},"898":{"law":"art. 25 ust. 1 Prawa o ruchu drogowym","text":"Знак A-5 попереджає про перехрестя рівнозначних доріг, де перевагу не визначають жодні знаки. Там діє правило правої руки: поступаєшся транспорту, що наближається праворуч."},"9012":{"text":"На гостроту зору водій впливає сам: через концентрацію, самопочуття і стан здоров'я, зокрема втому та зір. Погода, покриття і час доби це зовнішні умови, на які він не впливає."},"9035":{"text":"Що більша швидкість, то вужче поле зору: на 40 км/год воно охоплює близько ста градусів, на 130 км/год лише кілька десятків. Тому на швидкій дорозі легко не помітити те, що відбувається збоку."},"9058":{"law":"art. 60 ust. 2 pkt 2 Prawa o ruchu drogowym","text":"Надмірні викиди вихлопних газів і надмірний шум заборонені всюди, а не лише в місті чи житловій зоні. Норма захищає довкілля і людей на всій мережі доріг."},"9065":{"text":"ASR працює при передачі тяги на колеса, тож допомагає при різкому прискоренні на мокрому покритті. Під час спуску колеса не ведучі й системі нічого коригувати."},"9067":{"text":"ASR найбільше стає в пригоді при різкому рушанні на слизькому покритті, бо саме тоді ведучі колеса буксують. На спуску чи при рівномірному підйомі немає пробуксовування, яке треба обмежувати."},"9068":{"text":"ESP втручається там, де авто перестає триматися заданої траєкторії, тобто в крутому повороті. За сталої швидкості або на прямій стабілізувати нічого."},"9070":{"text":"Кілька поворотів поспіль це типова ситуація, коли кузов розгойдується і ESP коригує траєкторію. Тримати сталу швидкість це завдання круїз-контролю, а не ESP."},"916":{"text":"З часом за кермом увага слабшає, а не зростає: втома і монотонність знижують здатність помічати знаки та сигнали. Тому в довгій дорозі роблять перерви приблизно кожні дві години."},"974":{"text":"На табло змінної інформації показано попереджувальний знак про слизьку дорогу разом із закликом їхати обережно. Попереджувальний знак завжди сповіщає про місце, де небезпека є або може виникнути."},"975":{"law":"art. 3 ust. 1 Prawa o ruchu drogowym","text":"Над кожною смугою світиться знак A-30, тобто попередження про іншу небезпеку. Кожен попереджувальний знак зобов'язує дотримуватися особливої обережності аж до місця, якого він стосується."},"978":{"text":"Знак попереджає про приєднання дороги з одностороннім рухом: стрілка в символі показує, що транспорт звідти може лише виїхати на твою дорогу. Ця дорога другорядна, але водії з неї все одно часом вимушують перевагу."},"980":{"text":"Під знаком «дай дорогу» висить табличка T-6, яка малює справжній хід головної дороги через це перехрестя. Товста лінія це головна дорога, тонка це твій в'їзд."},"985":{"text":"Знак A-9 із символом шлагбаума попереджає про залізничний переїзд зі шлагбаумами або півшлагбаумами. Переїзд без шлагбаумів позначає знак A-10 із символом локомотива."},"986":{"text":"На знаку локомотив, тобто A-10: залізничний переїзд без шлагбаумів. Там ніщо не перекриє тобі дорогу перед потягом, тож переконуватися мусиш сам."},"987":{"text":"Символ локомотива означає знак A-10, тобто переїзд без шлагбаумів і без півшлагбаумів. Про шлагбауми повідомляв би знак A-9 із символом ґратки."},"988":{"text":"Знак A-11 попереджає про нерівну дорогу, тобто про поперечні нерівності покриття: колії, горби, вибоїни. Треба знизити швидкість, бо на нерівності авто втрачає зчеплення і стійкість."},"990":{"text":"Під знаком нерівної дороги висить табличка T-2 із довжиною ділянки: нерівності тягнуться 1,2 км. Табличка з довжиною завжди означає, наскільки далеко сягає небезпека, а не наскільки далеко до неї."},"991":{"text":"На знаку видно дві нерівності, тобто A-11: нерівна дорога, пошкоджене покриття. Про лежачого поліцейського попереджає A-11a, на якому лише одна виразна опуклість."},"992":{"text":"Знак A-11a з однією виразною опуклістю це штучна нерівність, укладена, щоб змусити їхати повільніше. Табличка вказує, що вона за 25 метрів після знака."},"994":{"text":"Табличка T-1 вказує відстань від знака до небезпечного місця, тут 25 метрів до штучної нерівності. Довжину самої небезпечної ділянки подає інша табличка, T-2."},"996":{"text":"Знак A-12a попереджає про звуження проїзної частини з обох боків. Вужча дорога це менше місця для роз'їзду, тож треба знизити швидкість і за потреби поступитися."}};
